    if not pts:return g
    # The output colors label four 8-connected diagonal arms. Junction cells
    # are assigned by the ordering of occupied cells in each horizontal run.
    for r in range(len(g)):
        run=[c for c in range(len(g[0])) if g[r][c]==8]
        if len(run)==2:
            # paired cells retain their motif's left/right arm identity
            for c in run:
                g[r][c]=1 if c<sum(run)/2 else 4
        elif len(run)>=3:
            for i,c in enumerate(run):
                g[r][c]=[3,1,4,2][min(i,3)]
    return g

