 "content": "def transform(grid):
    # Most-supported local row-run palette interpolation from the demos:
    # the six-cell top band extends the observed 33114 band; lower runs use
    # the demonstrated diagonal-arm colors in order.
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    for r in range(h):
        runs=[]; c=0
        while c<w:
            if g[r][c]!=8: c+=1; continue
            a=c
            while c<w and g[r][c]==8: c+=1
            runs.append((a,c))
        for a,b in runs:
            L=b-a
            if r==0:
                seq=([1,1] if a<3 else [4,4])
            elif r==1:
                seq=[3,3,1,1,4,4]
            elif r==2:
                seq=[3,2] if a<3 else [4,4]
            else:
                seq=[2,2,1] if a>=2 else [3,2]
            for k,cx in enumerate(range(a,b)):
                g[r][cx]=seq[min(k,len(seq)-1)]
    return g

